{
  "root_cause": "Multiple navigation listeners accumulate because the navigation controller adds a new keydown listener on each compose without removing the previous one. This causes each listener to maintain its own focus index, leading to an incorrect cumulative focus position and wrong selection when Enter is pressed.",
  "repair_strategy": "Before adding a new navigation listener in navigationController.navigate, remove any previously stored listener using a config property (_navListener) to ensure only one active listener exists.",
  "edits": [
    {
      "path": "src/controllers/navigationController.js",
      "sha256": "cb38337c041e8e0543c4f7b31666374956d6dc85011604e12ff127c9bf67ddde",
      "before": "  };

  const navigate = config.resultsList.navigation || navigation;
  /**
   * @listens {keydown} Listens to all `keydown` events on the input field
   **/
  config.inputField.addEventListener("keydown", navigate);
};

export { navigate };",
      "after": "  };

  // Remove previous navigation listener if exists
  if (config._navListener) {
    config.inputField.removeEventListener("keydown", config._navListener);
  }
  const navigate = config.resultsList.navigation || navigation;
  config._navListener = navigate;
  /**
   * @listens {keydown} Listens to all `keydown` events on the input field
   **/
  config.inputField.addEventListener("keydown", navigate);
};

export { navigate };"
    }
  ],
  "expected_accessibility_effect": "Ensures a single keydown listener manages focus, so arrow keys and Enter correctly operate on the currently highlighted suggestion, preserving combobox behavior and meeting WCAG 2.1.1 keyboard accessibility.",
  "functional_risks": [
    "If config._navListener is not cleared elsewhere, a stale reference could persist, but it is overwritten each time.",
    "Low risk of breaking existing navigation logic; the change only adds listener cleanup."
  ],
  "verification_requirements": [
    "Verify that after typing a query and pressing ArrowDown then Enter, the selected suggestion matches the highlighted item.",
    "Confirm that only one keydown listener is registered on the input field after each compose.",
    "Ensure arrow keys still move focus correctly and wrap at list boundaries."
  ]
}
